import React, { useState, useEffect } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import { useNavigate } from "react-router-dom";
import AdmListAluno from "./admlistaluno";
import AdmListCurso from "./admlistcurso";

const AdmListProf = () => {
  const [professores, setProfessores] = useState([]);
  const [filtro, setFiltro] = useState("");
  const navigate = useNavigate();

  // Função para buscar os professores no backend
  const fetchProfessores = async () => {
    try {
      const resposta = await fetch("http://localhost:5000/professores");
      if (resposta.ok) {
        const dados = await resposta.json();
        setProfessores(dados);
      } else {
        console.error("Erro ao buscar professores");
      }
    } catch (error) {
      console.error("Erro na requisição:", error);
    }
  };

  // Buscar professores assim que o componente for montado
  useEffect(() => {
    fetchProfessores();
  }, []);

  // Filtra os professores com base no nome
  const professoresFiltrados = professores.filter((professor) =>
    professor.nome.toLowerCase().includes(filtro.toLowerCase())
  );

  // Remover professor do backend e atualizar a lista
  const removerProfessor = async (id) => {
    try {
      const resposta = await fetch(`http://localhost:5000/professores/${id}`, {
        method: "DELETE",
      });

      if (resposta.ok) {
        fetchProfessores(); // Atualiza a lista após remover
      } else {
        console.error("Erro ao remover professor");
      }
    } catch (error) {
      console.error("Erro na requisição:", error);
    }
  };

  // Navega para a página de adicionar professor
  const navigateToAddProfessor = () => {
    navigate("/admaddprof");
  };

  // Navega para a página de editar professor
  const navigateToEditProfessor = (id) => {
    navigate(`/admeditprof/${id}`);
  };

  return (
    <div className="container mt-4">
      <h1 className="text-primary text-center">EducaWeb</h1>
      <ul className="nav nav-tabs justify-content-center mt-3">
        <li className="nav-item mx-2">
          <a className="nav-link" href="./admlistaluno">
            Cursos
          </a>
        </li>
        <li className="nav-item mx-2">
          <a className="nav-link active" href="#">
            Professores
          </a>
        </li>
        <li className="nav-item mx-2">
          <a className="nav-link" href="#">
            Alunos
          </a>
        </li>
      </ul>

      <div className="d-flex justify-content-between align-items-center mt-3">
        <h3>Professores</h3>
        <button className="btn btn-info" onClick={navigateToAddProfessor}>
          Adicionar
        </button>
      </div>

      <div className="mt-3">
        <input
          type="text"
          className="form-control"
          placeholder="Filtrar professores por nome"
          value={filtro}
          onChange={(e) => setFiltro(e.target.value)}
        />
      </div>

      <ul className="list-group mt-3">
        {professoresFiltrados.map((professor) => (
          <li
            key={professor.id}
            className="list-group-item d-flex justify-content-between align-items-center"
          >
            {professor.nome}
            <div>
              <button
                className="btn btn-outline-warning btn-sm mx-2"
                onClick={() => navigateToEditProfessor(professor.id)}
              >
                ✏️ Editar
              </button>
              <button
                className="btn btn-outline-danger btn-sm"
                onClick={() => removerProfessor(professor.id)}
              >
                🗑️ Remover
              </button>
            </div>
          </li>
        ))}
      </ul>
    </div>
  );
};

export default AdmListProf;
